    {
        var modeName = ThemeService.Mode switch
        {
            ThemeMode.Light => "light",
            ThemeMode.Dark => "dark",
            _ => "auto"
        };
        await JS.InvokeVoidAsync("ThemeInterop.apply", modeName, ThemeService.AccentColor);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

