+@*
+    Interactive island in the layout header that shows the current theme.
+    Shares the circuit-scoped ThemeService with all other interactive components.
+*@
+@rendermode InteractiveServer
+@implements IDisposable
+@inject ThemeService ThemeService
+
+<span class="theme-indicator" title="Current theme">
+    @GetThemeIcon() @ThemeService.Mode
+    <button class="btn btn-sm btn-outline-secondary ms-2" @onclick="CycleTheme">
+        Toggle
+    </button>
+</span>
+
+@code {
+    protected override void OnInitialized()
+    {
+        ThemeService.OnChange += HandleThemeChanged;
+    }
+
+    private void CycleTheme()
+    {
+        ThemeService.Mode = ThemeService.Mode switch
+        {
+            ThemeMode.Light => ThemeMode.Dark,
+            ThemeMode.Dark => ThemeMode.System,
+            _ => ThemeMode.Light
+        };
+    }
+
+    private string GetThemeIcon() => ThemeService.Mode switch
+    {
+        ThemeMode.Light => "☀️",
+        ThemeMode.Dark => "🌙",
+        _ => "💻"
+    };
+
+    private async void HandleThemeChanged()
+    {
+        await InvokeAsync(StateHasChanged);
+    }
+
+    public void Dispose()
+    {
+        ThemeService.OnChange -= HandleThemeChanged;
+    }
+}
+

